      thm = x[2] + 0.5 * w * dt;
    const o = dyn ? mpcDynPose(x, v, s, dt, G, iy) : [x[0] + v * Math.cos(thm) * dt, x[1] + v * Math.sin(thm) * dt, x[2] + w * dt, 0, 0];
