  // after any interruption (replan tick, controller switch) start again from the measured actuator state
  const LC = S.mpcCmd && S.mpcCmd.tick === S.tick - 1 ? S.mpcCmd : {v: S.odo.v, steer: S.robot.d, w: S.odo.w};
